import * as THREE from 'three';
const RT = 1024; // never 512 or lower: that is what reads as "blocky / stepped rectangles"
const mirrorRT = new THREE.WebGLRenderTarget(RT, RT, { minFilter: THREE.LinearFilter, magFilter: THREE.LinearFilter });
const mirrorCam = new THREE.PerspectiveCamera();
const texMat = new THREE.Matrix4(), UP = new THREE.Vector3(0, 1, 0);
export function renderMirror(renderer, scene, camera, water) {   // call once per frame, before the main render
  const waterY = water.position.y;
  const pos = camera.getWorldPosition(new THREE.Vector3()), dir = camera.getWorldDirection(new THREE.Vector3());
  mirrorCam.fov = camera.fov; mirrorCam.aspect = camera.aspect; mirrorCam.near = camera.near; mirrorCam.far = camera.far;
  mirrorCam.position.set(pos.x, 2 * waterY - pos.y, pos.z);
  mirrorCam.up.set(0, -1, 0);                                      // reflected up-vector, as in three's Reflector
  mirrorCam.lookAt(pos.x + dir.x, 2 * waterY - (pos.y + dir.y), pos.z + dir.z);
  mirrorCam.updateProjectionMatrix(); mirrorCam.updateMatrixWorld();
  texMat.set(0.5, 0, 0, 0.5, 0, 0.5, 0, 0.5, 0, 0, 0.5, 0.5, 0, 0, 0, 1)
    .multiply(mirrorCam.projectionMatrix).multiply(mirrorCam.matrixWorldInverse);
  water.visible = false;
  renderer.clippingPlanes = [new THREE.Plane(UP, -waterY)];       // keep only what is above the waterline
  renderer.setRenderTarget(mirrorRT); renderer.render(scene, mirrorCam); renderer.setRenderTarget(null);
  renderer.clippingPlanes = []; water.visible = true;
  water.material.uniforms.uMirror.value = mirrorRT.texture;
  water.material.uniforms.uTexMat.value.copy(texMat);
}
export const waterMaterial = new THREE.ShaderMaterial({
  uniforms: { uMirror: { value: null }, uTexMat: { value: new THREE.Matrix4() }, uTime: { value: 0 }, uBase: { value: new THREE.Color(0x2b3324) } },
  vertexShader: 'uniform mat4 uTexMat; varying vec4 vM; varying vec3 vW; void main(){ vec4 w = modelMatrix * vec4(position, 1.0); vW = w.xyz; vM = uTexMat * w; gl_Position = projectionMatrix * viewMatrix * w; }',
  fragmentShader: [
    'uniform sampler2D uMirror; uniform float uTime; uniform vec3 uBase; varying vec4 vM; varying vec3 vW;',
    'void main(){ vec2 uv = vM.xy / vM.w;',
    '  float chop = 0.006 * sin(vW.x * 21.0 + uTime * 1.7) + 0.003 * sin(vW.z * 37.0 - uTime * 2.3) + 0.001 * sin((vW.x + vW.z) * 61.0 + uTime * 3.1);',
    '  uv.x += chop;                                   // horizontal only, total amplitude <= 0.01 UV',
    '  vec3 refl = texture2D(uMirror, uv).rgb;',
    '  vec3 V = normalize(cameraPosition - vW); float f = pow(1.0 - max(dot(vec3(0.0, 1.0, 0.0), V), 0.0), 3.0);',
    '  gl_FragColor = vec4(mix(uBase, refl, 0.06 + 0.24 * f), 1.0); }' // reflectivity capped ~0.3: mirror legible, base still dark
  ].join('\n')
});
